use crate::aap::caps::{http_client, notifier};
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Clock: read the current time.
        let seconds = wall_clock::now().seconds;

        // HTTPClient: the one permitted fetch. A transport failure is carried
        // as a value (zero characters fetched); a request outside the
        // allowlist traps at the boundary, as it should.
        let (fetched, fetch_ok) = match http_client::fetch(&feed_url) {
            Ok(body) => (u32::try_from(body.chars().count()).unwrap_or(u32::MAX), true),
            Err(_) => (0u32, false),
        };

        // Notifier: report the heartbeat. Only values this node computed go
        // into the message; none of the fetched (untrusted) text is forwarded.
        let message = if fetch_ok {
            format!("heartbeat: time={}s fetched={} chars", seconds, fetched)
        } else {
            format!("heartbeat: time={}s fetch failed", seconds)
        };
        let notified = notifier::notify(&message);

        // Contract: ensures notified == true. If the notification was not
        // accepted, there is no honest output satisfying the contract, so the
        // node produces none: it traps rather than fabricating `true`.
        if !notified {
            panic!("heartbeat notification was not accepted");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
